#!/usr/bin/env python3
"""
Groq STT Proxy for Voice Mode

This proxy translates OpenAI Whisper API calls to Groq's Whisper API.
Voice Mode uses 'whisper-1' model, but Groq uses 'whisper-large-v3'.

Usage:
    OPENAI_API_KEY=[REDACTED] python groq-proxy.py

The proxy runs on port 5051 by default.
"""

from flask import Flask, request, Response
import requests
import os

app = Flask(__name__)

GROQ_API_KEY = [REDACTED]'GROQ_API_KEY') or os.environ.get('OPENAI_API_KEY')
GROQ_URL = "https://api.groq.com/openai/v1/audio/transcriptions"
PORT = int(os.environ.get('GROQ_PROXY_PORT', 5051))

# Model mapping: Voice Mode model -> Groq model
MODEL_MAP = {
    'whisper-1': 'whisper-large-v3',
    'whisper': 'whisper-large-v3',
}


@app.route('/v1/audio/transcriptions', methods=['POST'])
def transcribe():
    """Proxy transcription requests to Groq."""
    # Translate model name
    model = request.form.get('model', 'whisper-1')
    groq_model = MODEL_MAP.get(model, 'whisper-large-v3')

    # Forward file and other fields
    files = {'file': (request.files['file'].filename, request.files['file'].read())}
    data = {'model': groq_model}

    # Optional fields
    for field in ['language', 'prompt', 'response_format', 'temperature']:
        if field in request.form:
            data[field] = request.form[field]

    # Forward to Groq
    headers = {'Authorization': f'Bearer {GROQ_API_KEY}'}
    resp = requests.post(GROQ_URL, headers=headers, files=files, data=data)

    return Response(
        resp.content,
        status=resp.status_code,
        content_type=resp.headers.get('content-type')
    )


@app.route('/v1/models', methods=['GET'])
def models():
    """Return available models."""
    return {
        'data': [
            {'id': 'whisper-1'},
            {'id': 'whisper-large-v3'},
            {'id': 'whisper-large-v3-turbo'},
        ]
    }


@app.route('/health', methods=['GET'])
def health():
    """Health check endpoint."""
    return {'status': 'ok', 'groq_key_set': bool(GROQ_API_KEY)}


if __name__ == '__main__':
    if not GROQ_API_KEY:
        print("WARNING: No API key set!")
        print("Set OPENAI_API_KEY or GROQ_API_KEY environment variable")
    else:
        print(f"API Key: {GROQ_API_KEY[:20]}...")

    print(f"Groq STT Proxy running on port {PORT}")
    app.run(host='127.0.0.1', port=PORT)
